from datetime import date, timedelta

def calc_fallback(year, week, day):
    if not 0 < week < 54:
        raise ValueError("Invalid week: {}".format(week))
    if not 0 < day < 8:
        raise ValueError("Invalid weekday: {}".format(day))
    jan_4 = date(year, 1, 4)
    week_1 = jan_4 - timedelta(days=jan_4.isocalendar()[2] - 1)
    week_offset = (week - 1) * 7 + (day - 1)
    ret = week_1 + timedelta(days=week_offset)
    if ret.isocalendar()[:2] != (year, week):
        raise ValueError("Invalid week: {} for year {}".format(week, year))
    return ret

# Test with fromisocalendar vs calc_fallback for years 1..9999
for y in [1, 2, 2004, 2009, 2020, 2021, 2022, 2023, 2024, 9998]:
    for w in [1, 52, 53]:
        for d in [1, 7]:
            try:
                exp = date.fromisocalendar(y, w, d)
                exp_err = None
            except ValueError as e:
                exp = None
                exp_err = type(e)
            try:
